import React, { useState } from 'react';
import { Button } from './components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { motion } from 'framer-motion';

export default function NourishLink() {
  const [userType, setUserType] = useState(null);
  const [donations, setDonations] = useState([]);
  const [newDonation, setNewDonation] = useState({ item: '', quantity: '' });

  const foodItems = ['Rice', 'Bread', 'Fruits', 'Vegetables', 'Dairy Products'];

  const quantityUnits = {
    'Rice': ['1 kg', '5 kg', '10 kg'],
    'Bread': ['1 loaf', '2 loaves', '5 loaves'],
    'Fruits': ['1 kg', '2 kg', '5 kg'],
    'Vegetables': ['1 kg', '3 kg', '5 kg'],
    'Dairy Products': ['1 L', '2 L', '5 L']
  };

  const handleDonationSubmit = () => {
    if (newDonation.item && newDonation.quantity) {
      setDonations([...donations, newDonation]);
      setNewDonation({ item: '', quantity: '' });
    }
  };

  const handleClaimDonation = (index) => {
    const updatedDonations = donations.filter((_, i) => i !== index);
    setDonations(updatedDonations);
  };

  return (
    <div className="min-h-screen bg-black text-white p-6 space-y-8">
      <motion.h1 
        className="text-4xl font-bold text-center mb-8"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        NourishLink
      </motion.h1>

      {!userType ? (
        <motion.div 
          className="flex flex-col items-center justify-center space-y-4"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
        >
          <Button onClick={() => setUserType('donor')} className="w-40 bg-green-600 hover:bg-green-700">Login as Donor</Button>
          <Button onClick={() => setUserType('ngo')} className="w-40 bg-blue-600 hover:bg-blue-700">Login as NGO</Button>
        </motion.div>
      ) : (
        <motion.div 
          className="space-y-6"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
        >
          <h2 className="text-3xl font-semibold text-center">
            {userType === 'donor' ? 'Post a Donation' : 'Available Donations'}
          </h2>

          {userType === 'donor' ? (
            <div className="space-y-4 max-w-md mx-auto">
              <select 
                value={newDonation.item} 
                onChange={(e) => setNewDonation({ ...newDonation, item: e.target.value })}
                className="w-full p-3 rounded bg-gray-800 text-white border border-gray-700"
              >
                <option value="" disabled>Select Food Item</option>
                {foodItems.map((item, index) => (
                  <option key={index} value={item}>{item}</option>
                ))}
              </select>

              <select 
                value={newDonation.quantity} 
                onChange={(e) => setNewDonation({ ...newDonation, quantity: e.target.value })}
                className="w-full p-3 rounded bg-gray-800 text-white border border-gray-700"
                disabled={!newDonation.item}
              >
                <option value="" disabled>Select Quantity</option>
                {newDonation.item && quantityUnits[newDonation.item].map((quantity, index) => (
                  <option key={index} value={quantity}>{quantity}</option>
                ))}
              </select>

              <Button onClick={handleDonationSubmit} className="w-full bg-green-500 hover:bg-green-600">Submit Donation</Button>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {donations.length > 0 ? (
                donations.map((donation, index) => (
                  <Card key={index} className="bg-gray-800 text-white p-4 rounded-2xl shadow-lg">
                    <CardContent>
                      <h3 className="text-xl font-semibold mb-2">{donation.item}</h3>
                      <p className="mb-4">Quantity: {donation.quantity}</p>
                      <Button onClick={() => handleClaimDonation(index)} className="bg-red-500 hover:bg-red-600">Claim Donation</Button>
                    </CardContent>
                  </Card>
                ))
              ) : (
                <p className="text-center col-span-full">No donations available at the moment.</p>
              )}
            </div>
          )}

          <Button onClick={() => setUserType(null)} className="w-full mt-6 bg-gray-700 hover:bg-gray-800">Logout</Button>
        </motion.div>
      )}
    </div>
  );
}
